// Golden tests: every case here was generated by the Python engine
// (test/golden/*.json, produced by parser.py). The Dart engine must match.

import 'dart:convert';
import 'dart:io';

import 'package:railway_clean_ip_scanner/engine/vless_parser.dart';
import 'package:test/test.dart';

List<dynamic> _load(String name) {
  final text = File('test/golden/$name').readAsStringSync();
  return jsonDecode(text) as List<dynamic>;
}

void main() {
  group('parse (golden from parser.py)', () {
    for (final raw in _load('parse.json')) {
      final c = raw as Map<String, dynamic>;
      final input = c['input'] as String;
      final expected = c['expected'] as Map<String, dynamic>?;
      test(input.length > 80 ? input.substring(0, 80) : input, () {
        final cfg = parse(input);
        if (expected == null) {
          expect(cfg, isNull);
          return;
        }
        expect(cfg, isNotNull);
        expect(cfg!.uuid, expected['uuid']);
        expect(cfg.address, expected['address']);
        expect(cfg.port, expected['port']);
        expect(cfg.domain, expected['domain']);
        expect(cfg.path, expected['path']);
        expect(cfg.security, expected['security']);
        expect(cfg.type, expected['type']);
        expect(cfg.name, expected['name']);
      });
    }
  });

  group('split_candidates (golden)', () {
    for (final raw in _load('split.json')) {
      final c = raw as Map<String, dynamic>;
      final input = c['input'] as String;
      final expected = (c['expected'] as List<dynamic>).cast<String>();
      test(jsonEncode(input).length > 60 ? jsonEncode(input).substring(0, 60) : jsonEncode(input), () {
        expect(splitCandidates(input), equals(expected));
      });
    }
  });

  group('parse_first (golden)', () {
    for (final raw in _load('parse_first.json')) {
      final c = raw as Map<String, dynamic>;
      final input = c['input'] as String;
      test(jsonEncode(input).length > 60 ? jsonEncode(input).substring(0, 60) : jsonEncode(input), () {
        final (cfg, found) = parseFirst(input);
        expect(found, c['found']);
        final expected = c['expected'] as Map<String, dynamic>?;
        if (expected == null) {
          expect(cfg, isNull);
        } else {
          expect(cfg, isNotNull);
          expect(cfg!.domain, expected['domain']);
          expect(cfg.name, expected['name']);
          expect(cfg.address, expected['address']);
        }
      });
    }
  });

  group('build_config_link (golden)', () {
    for (final raw in _load('build.json')) {
      final c = raw as Map<String, dynamic>;
      test('build for ${c['ip']}', () {
        final VlessConfig base;
        if (c.containsKey('base_link')) {
          final parsed = parse(c['base_link'] as String);
          expect(parsed, isNotNull);
          base = parsed!;
        } else {
          final f = c['base_fields'] as Map<String, dynamic>;
          base = VlessConfig(
            uuid: f['uuid'] as String,
            address: f['address'] as String,
            port: f['port'] as int,
            domain: f['domain'] as String,
            path: f['path'] as String,
            security: f['security'] as String,
            type: f['type'] as String,
            name: f['name'] as String,
          );
        }
        expect(buildConfigLink(base, c['ip'] as String), equals(c['expected']));
      });
    }
  });
}
